/**
 * Dynamically synthesizes a brand-new, unique drill on demand using ChatGPT/Gemini combinatorial knowledge
 */
export function generateDynamicDrill(language = "Java", topic = "Backend", roundType = "TR", difficulty = "Hard") {
  const seed = Date.now() + Math.floor(Math.random() * 10000);
  const langKey = Object.keys(LANGUAGE_TR_KNOWLEDGE).find(
    (k) => k.toLowerCase() === language.toLowerCase()
  ) || "Java";
  const langData = LANGUAGE_TR_KNOWLEDGE[langKey] || LANGUAGE_TR_KNOWLEDGE["Java"];

  if (roundType === "HR" || topic === "Behavioral") {
    const hrQuestions = LANGUAGE_HR_KNOWLEDGE.general || [];
    const hrItem = hrQuestions[seed % hrQuestions.length];
    const qText = hrItem ? hrItem.question(language) : `Describe a challenging production engineering incident in ${language} and how you led resolution.`;
    const ansText = hrItem ? hrItem.sampleAnswer(language) : "In my work with " + language + ", I triaged the issue, communicated with stakeholders, and conducted a blameless post-mortem.";

    return {
      id: `ai-drill-${language.toLowerCase()}-${seed}`,
      language,
      roundType: "HR",
      topic: "Behavioral",
      difficulty: difficulty === "All" ? "Medium" : difficulty,
      questionText: qText,
      hint: "Structure your response using the STAR framework: Situation, Task, Action, and measurable Result.",
      modelAnswer: ansText,
      strengths: ["Clear STAR progression", "Quantified business and engineering metrics", "Blameless post-mortem ownership"],
      missingConcepts: ["Long-term automated CI guardrails", "Stakeholder communications protocol"],
      isAiGenerated: true,
    };
  }

  // TR Technical Round Dynamic Generation
  const scenario = PRODUCTION_SCENARIOS[seed % PRODUCTION_SCENARIOS.length];
  const mechanics =
    langData.coreMechanics?.[seed % (langData.coreMechanics?.length || 1)] ||
    "concurrency and memory management";
  const expectedQ =
    langData.mostlyExpectedInterviewQuestions?.[
      seed % (langData.mostlyExpectedInterviewQuestions?.length || 1)
    ];
  const debuggingQ =
    langData.debuggingScenarios?.[
      (seed + 1) % (langData.debuggingScenarios?.length || 1)
    ];
  const architectureQ =
    langData.architectureQuestions?.[
      (seed + 2) % (langData.architectureQuestions?.length || 1)
    ];

  const isHighFrequency = seed % 3 === 0 && Boolean(expectedQ);

  let questionText;
  if (isHighFrequency) {
    questionText = expectedQ;
  } else if (seed % 3 === 1 && debuggingQ) {
    questionText = debuggingQ;
  } else if (architectureQ && seed % 4 === 0) {
    questionText = architectureQ;
  } else {
    questionText = `In a ${scenario.context} built with ${language}: Suppose the system encounters ${scenario.failure}. How would you diagnose the root cause and resolve it?`;
  }

  const modelAnswer = isHighFrequency
    ? `Recommended High-Frequency Technical Model Answer for ${language}:\n1. Core Principle & Memory Representation: Explain runtime semantics, memory placement (heap vs stack), and why language designers created this abstraction.\n2. Concurrency & Failure Invariants: Detail thread safety guarantees, state immutability, and boundary edge cases.\n3. Production Best Practice: When to choose this over alternatives, and how to verify correctness using unit tests or profiling tools.`
    : `1. Immediate Triage & Observability:\nInspect application performance metrics: p99 latency spikes, CPU/memory saturation, thread pools, and connection states. Capture low-level runtime profiles and heap dumps to isolate the exact bottleneck.\n\n2. Root Cause Analysis involving ${mechanics}:\nIdentify whether the failure stems from thread contention, GC thrashing, lock starvation, or unindexed queries. Correlate with upstream traffic bursts.\n\n3. Architectural Remediation:\n- Introduce backpressure, request shedding, or circuit breakers to protect downstream resources.\n- Optimize code around ${mechanics} to ensure non-blocking, memory-efficient execution.\n- Add automated canary alerts and regression tests in CI.`;

  return {
    id: `ai-drill-${language.toLowerCase()}-${seed}`,
    language,
    roundType: "TR",
    topic: topic === "All" ? (isHighFrequency ? "DSA" : "Backend") : topic,
    difficulty: difficulty === "All" ? "Hard" : difficulty,
    questionText,
    hint: isHighFrequency
      ? `Focus on standard interview fundamentals, memory management, and practical production trade-offs in ${language}.`
      : `Focus on root-cause analysis, metrics inspection, and how ${mechanics} prevents cascading failure.`,
    modelAnswer,
    strengths: [
      `Systematic technical breakdown for ${language}`,
      "Concrete runtime mechanics and memory lifecycle explanation",
      "Actionable architectural remediation and resilience guarantees",
    ],
    missingConcepts: [
      "Failure domain isolation and edge case verification",
      "Graceful degradation strategies during high traffic",
    ],
    isHighFrequency,
    isAiGenerated: true,
  };
}
